Deno.serve(async () => {
  const sb = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
  let ok = 0; const errs: string[] = [];
  for (const r of DATA) {
    const { error } = await sb.from(r.t).update({ meta_keywords_pt: r.pt, meta_keywords_es: r.es }).eq('id', r.id);
    if (error) errs.push(r.id + ': ' + error.message); else ok++;
  }
  return new Response(JSON.stringify({ ok, errs }), { headers: { 'Content-Type': 'application/json' } });
});
